export const teamName=name=>TEAM_ALIASES[name]||name;
const DISPLAY_NAME_PATTERN=new RegExp(Object.keys(TEAM_ALIASES).sort((a,b)=>b.length-a.length).map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
export const displayNames=value=>String(value??'').replace(DISPLAY_NAME_PATTERN,name=>TEAM_ALIASES[name]);
