export const TEAM_CATALOG=[["domestic-central",["osaka","yokohama","tokyo","nagoya","jingu","hiroshima"]],["domestic-pacific",["fukuoka","hokkaido","chiba","kobe","sendai","saitama"]],["overseas-frontier",["boston","new-york","toronto","chicago-white","houston","anaheim"]],["overseas-continental",["cincinnati","chicago-grizzly","arizona","los-angeles","san-diego"]]].flatMap(([leagueId,ids],i)=>[...DOMESTIC_LEAGUES,...OVERSEAS_LEAGUES][i].teams.map((name,j)=>({id:leagueId+'-'+ids[j],name,leagueId,colors:null,logo:null})));
// Normalize legacy data without touching player names, IDs, statistics or RNG state.
export function migrateTeamNames(s){
 const fields=new Set(['team','from','to','league','text','message','body','news','teams']);
 function walk(value,key=''){if(typeof value==='string')return fields.has(key)?displayNames(value):value;if(!value||typeof value!=='object')return value;if(Array.isArray(value)){for(let i=0;i<value.length;i++)value[i]=walk(value[i],key);}else for(const k of Object.keys(value)){if(k!=='player')value[k]=walk(value[k],k);}return value;}
 return walk(s);
}

